# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: `ds ui` commands for the Reflex apps. `restart` restarts delulu-smash (the
# services/ui app, run by the delulu-smash.service systemd user service) and
# waits until it answers, eg so it picks up keys just stored with `ds settings sync`.
#
# Example CLI Commands:
#   1. Restart delulu-smash:  ds ui restart
# ---------------------------------------------------------------------------
from __future__ import annotations

import time
import urllib.request
from http import HTTPStatus

import typer
from ds.cli.util import run_cmd
from ds.util.const import REPO_DIR

__all__ = ["ui_app"]


ui_app = typer.Typer(help="SubCommands for reflex ui tool")

TOOLS_DIR = REPO_DIR / "tools" / "smash"

# Same service and URLs as .os/scripts/keybindings/delulu-smash.py
APP_SERVICE = "delulu-smash.service"
APP_URLS = ("http://localhost:3000", "http://127.0.0.1:8000/ping")  # page, backend
# A cold `reflex run` (frontend build + dev server) takes about a minute.
APP_START_TIMEOUT_S = 150


def _up(url: str) -> bool:
    try:
        with urllib.request.urlopen(url, timeout=2) as response:  # noqa: S310  # fixed localhost URLs
            return response.status < HTTPStatus.INTERNAL_SERVER_ERROR
    except OSError:
        return False


@ui_app.command("run")
def run() -> None:
    """Run reflex ui server"""
    run_cmd(["uv", "run", f"--directory={TOOLS_DIR}", "reflex", "run"])


@ui_app.command("restart")
def restart() -> None:
    """Restart delulu-smash (delulu-smash.service) and wait until it answers

    Its server reads stored keys once at start, so run this after `ds settings sync`.
    """
    run_cmd(["systemctl", "--user", "restart", APP_SERVICE])
    typer.echo("Waiting for delulu-smash to answer (up to about a minute)...")
    deadline = time.monotonic() + APP_START_TIMEOUT_S
    while not all(_up(url) for url in APP_URLS):
        if time.monotonic() > deadline:
            typer.echo(f"delulu-smash didn't come up. Logs: journalctl --user -u {APP_SERVICE}", err=True)
            raise typer.Exit(1)
        time.sleep(1)
    typer.echo(f"delulu-smash is up: {APP_URLS[0]}")
